15	// RunDesignationSummary is the prompt/API-safe designation projection for run summaries.
16	type RunDesignationSummary struct {
17		Index int    `json:"index"`
18		Brief string `json:"brief,omitempty"`
19	}
20	
21	// DesignationFromRun extracts the fan-out assignment metadata from a task run.
22	func DesignationFromRun(run Run) (RunDesignation, bool) {
23		groupID := strings.TrimSpace(run.DesignationGroupID)
24		if groupID == "" {
25			return RunDesignation{}, false
26		}
27		designation := RunDesignation{GroupID: groupID}
28		if len(run.Metadata) == 0 {
29			return designation, true
30		}
31		var payload struct {
32			Designation struct {
33				Index int    `json:"index"`
34				Brief string `json:"brief"`
35			} `json:"designation"`
36		}
37		if err := json.Unmarshal(run.Metadata, &payload); err != nil {
38			return designation, true
39		}
40		designation.Index = payload.Designation.Index
41		designation.Brief = strings.TrimSpace(payload.Designation.Brief)
42		return designation, true
43	}
44	
45	// Summary returns the prompt/API-safe projection of a run designation.
46	func (d RunDesignation) Summary() *RunDesignationSummary {
47		return &RunDesignationSummary{
48			Index: d.Index,
49			Brief: strings.TrimSpace(d.Brief),
50		}
51	}
